public class SmokeCheck
{
    /* One line of the report: which step, what it proves, and what came back. */
    public string step { get; set; }
    public string check { get; set; }
    public string capability { get; set; }
    public bool passed { get; set; }
    public string detail { get; set; }
}

types.SmokeReport:
public class SmokeReport
{
    /* The caller's label for this run, as given in the request. */
    public string run { get; set; }
    /* The host and engine versions of the process that ran the test. */
    public string platform { get; set; }
    public string engine { get; set; }
    public string startedUtc { get; set; }
    public string finishedUtc { get; set; }
    public int total { get; set; }
    public int failed { get; set; }
    public bool passed { get; set; }
    public System.Collections.Generic.List<SmokeCheck> checks { get; set; } = new System.Collections.Generic.List<SmokeCheck>();

    public static SmokeReport Ensure(SmokeReport report)
    {
        return report ?? new SmokeReport() { startedUtc = System.DateTime.UtcNow.ToString("o") };
    }

    /* A step threw: its boundary event led here. */
    public void Error(string step, string check, System.Exception error)
    {
        checks.Add(new SmokeCheck() { step = step, check = check, capability = "the step runs", passed = false,
            detail = error == null ? "failed without an exception" : error.GetType().Name + ": " + error.Message });
    }

    /* The called Flow answered: check the answer. A step that already threw is not checked twice. */
    public void Expect(string step, string check, string capability, object result, string marker, bool failureExpected)
    {
        if (checks.Exists(c => c.step == step))
            return;
        string text = null;
        if (result != null)
            text = result is string s ? s
                 : result.GetType().Name == "JSON" ? result.ToString()
                 : Newtonsoft.Json.JsonConvert.SerializeObject(result);
        string failure = null;
        if (text != null && text.TrimStart().StartsWith("{"))
        {
            var answer = Newtonsoft.Json.Linq.JObject.Parse(text);
            var code = answer["statusCode"];
            if (answer["levelMessage"] != null && code != null && ((int)code < 200 || (int)code > 299))
                failure = (string)answer["message"] ?? "no message";
        }
        bool passed;
        string detail;
        if (failureExpected)
        {
            /* the failure branch must answer for the reason the check names, not for any reason */
            passed = failure != null && failure.IndexOf(marker, System.StringComparison.OrdinalIgnoreCase) >= 0;
            detail = passed ? "the failure branch answered: " + failure
                   : failure != null ? "the failure branch answered, but not with '" + marker + "': " + failure
                   : "expected the failure branch, got: " + Cut(text);
        }
        else if (text == null)
        {
            passed = false;
            detail = "no answer: the called Flow ended without a result, usually an unhandled error inside it (see its trace)";
        }
        else if (failure != null)
        {
            passed = false;
            detail = "the failure branch answered: " + failure;
        }
        else
        {
            passed = text.IndexOf(marker, System.StringComparison.OrdinalIgnoreCase) >= 0;
            detail = passed ? Cut(text) : "no '" + marker + "' in: " + Cut(text);
        }
        checks.Add(new SmokeCheck() { step = step, check = check, capability = capability, passed = passed, detail = detail });
    }

    public SmokeReport Finish()
    {
        total = checks.Count;
        failed = checks.FindAll(c => !c.passed).Count;
        passed = total > 0 && failed == 0;
        finishedUtc = System.DateTime.UtcNow.ToString("o");
        return this;
    }

    private static string Cut(string text)
    {
        if (text == null) return "null";
        return text.Length <= 300 ? text : text.Substring(0, 300) + "...";
    }
}
